# Build output grid
# Thresholds: cols 0-4 → 2, cols 5-10 → 4, cols 11+ → 3
markers = [18, 19, 6, 10, 1, 22, 5, 20, 10, 3, 18, 23, 9, 9, 15, 7]

output = []
for col in markers:
    if col <= 4:
        val = 2
    elif col <= 10:
        val = 4
    else:
        val = 3
    output.append([val] * 27)

print("Output grid:")
for i, row in enumerate(output):
    print(f"Row {i}: marker col={markers[i]}, value={row[0]}")

# Apply the pattern to test input
test_markers = [18, 19, 6, 10, 1, 22, 5, 20, 10, 3, 18, 23, 9, 9, 15, 7]

def col_to_value(c):
    if c <= 4:
        return 2
    elif c <= 9:
        return 4
    else:
        return 3

output_values = [col_to_value(m) for m in test_markers]
print("Output values:")
for i, (c, v) in enumerate(zip(test_markers, output_values)):
    print(f"Row {i}: col {c} → value {v}")

# Now build the grid
grid = [[v]*27 for v in output_values]
print("\nGrid:")
for i, row in enumerate(grid):
    print(f"Row {i}: value={row[0]}")
